(() => {
  const sel = ['body','h1','h2','.mark','p','.lede','label','input','button','.card','.foot'];
  const out = [];
  for (const s of sel) {
    document.querySelectorAll(s).forEach((el, i) => {
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      out.push({
        s: s + (document.querySelectorAll(s).length>1 ? '['+i+']' : ''),
        text: (el.innerText||'').slice(0,40),
        fontSize: cs.fontSize,
        lineHeight: cs.lineHeight,
        fontFamily: cs.fontFamily.split(',')[0],
        h: Math.round(r.height),
        w: Math.round(r.width),
        pad: cs.padding,
        border: cs.borderTopWidth
      });
    });
  }
  return out;
})()

(() => {
  const nodes = [...document.querySelectorAll('body *')].filter(el => el.getClientRects().length);
  const rows = nodes.map(el => {
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    const tag = el.tagName.toLowerCase();
    const cls = el.className && typeof el.className === 'string' ? '.'+el.className.trim().split(/\s+/).join('.') : '';
    return {
      el: tag+cls,
      fs: cs.fontSize,
      lh: cs.lineHeight,
      h: Math.round(r.height*10)/10,
      pad: cs.padding,
      bw: cs.borderTopWidth,
      ff: cs.fontFamily.slice(0,18)
    };
  });
  // unique by el+fs+h rounded
  const seen = new Map();
  for (const row of rows) {
    const k = row.el+'|'+row.fs+'|'+row.h+'|'+row.bw;
    if (!seen.has(k)) seen.set(k, row);
  }
  return [...seen.values()];
})()

